def is_valid_brackets(text: str) -> bool:
    """正则语言做不到的经典问题：需要栈（下推自动机）。"""
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs and (not stack or stack.pop() != pairs[ch]):
            return False
    return not stack

