def lower_bound(nums, target):
    left, right = 0, len(nums)
    while left < right:                 # 左闭右开区间
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left

def bubble_sort(nums):
    n = len(nums)
    for i in range(n - 1):
        swapped = False
        # 每一轮比较到 n-1-i，后面已经有序
        for j in range(n - 1 - i):
            if nums[j] > nums[j + 1]:
                nums[j], nums[j + 1] = nums[j + 1], nums[j]
                swapped = True
        if not swapped:      # 本轮没有交换，说明已经有序
            break
    return nums

