                return False
    return not stack

# 队列用 deque，两端都是 O(1)
def bfs(graph, start):
    queue = deque([start])
    visited = {start}
    order = []
    while queue:
        node = queue.popleft()       # 不要用 list.pop(0)
        order.append(node)
        for nxt in graph.get(node, []):
            if nxt not in visited:
                visited.add(nxt)
                queue.append(nxt)
    return order

def preorder(node):        # 根 -> 左 -> 右
    if not node:
        return []
    return [node.value] + preorder(node.left) + preorder(node.right)

def inorder(node):         # 左 -> 根 -> 右：二叉搜索树得到升序
    if not node:
        return []
    return inorder(node.left) + [node.value] + inorder(node.right)

def postorder(node):       # 左 -> 右 -> 根：适合释放资源
    if not node:
        return []
    return postorder(node.left) + postorder(node.right) + [node.value]

from collections import deque

def level_order(root):     # 层序遍历（BFS）
    if not root:
        return []
    result, queue = [], deque([root])
    while queue:
        level = []
        for _ in range(len(queue)):
            node = queue.popleft()
            level.append(node.value)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        result.append(level)
    return result

def insertion_sort(nums):
    for i in range(1, len(nums)):
        current, j = nums[i], i - 1
        while j >= 0 and nums[j] > current:
            nums[j + 1] = nums[j]
            j -= 1
        nums[j + 1] = current
    return nums

def permute(nums):
    result, path, used = [], [], [False] * len(nums)
    def backtrack():
        if len(path) == len(nums):
            result.append(path[:])       # 拷贝！否则后续修改会影响结果
            return
        for i, value in enumerate(nums):
            if used[i]:
                continue
            used[i] = True
            path.append(value)
            backtrack()
            path.pop()                    # 撤销选择
            used[i] = False
    backtrack()
    return result

import heapq

def max_meetings(intervals):
    """最多不重叠会议：按结束时间升序贪心。"""
    intervals = sorted(intervals, key=lambda x: x[1])
    count, last_end = 0, float("-inf")
    for start, end in intervals:
        if start >= last_end:
            count += 1
            last_end = end
    return count

def min_coins(coins, amount):
    """硬币找零：面值不保证规范时必须用 DP，这里给出通用解。"""
    dp = [float("inf")] * (amount + 1)
    dp[0] = 0
    for value in range(1, amount + 1):
        for coin in coins:
            if coin <= value:
                dp[value] = min(dp[value], dp[value - coin] + 1)
    return -1 if dp[amount] == float("inf") else dp[amount]

def schedule_tasks(tasks):
    """按截止时间安排任务，超期时丢弃最耗时的任务。"""
    tasks.sort(key=lambda t: t[1])
    chosen, total = [], 0
    for duration, deadline in tasks:
        total += duration
        heapq.heappush(chosen, -duration)
        if total > deadline:
            total += heapq.heappop(chosen)   # 弹出的负数等于减去该耗时
    return len(chosen)

def build_prefix_2d(matrix):
    rows, cols = len(matrix), len(matrix[0])
    prefix = [[0] * (cols + 1) for _ in range(rows + 1)]
    for r in range(rows):
        for c in range(cols):
            prefix[r + 1][c + 1] = (matrix[r][c]
                + prefix[r][c + 1] + prefix[r + 1][c] - prefix[r][c])
    return prefix

def rect_sum(prefix, r1, c1, r2, c2):   # 左上 (r1,c1) 到右下 (r2,c2)
    return (prefix[r2 + 1][c2 + 1] - prefix[r1][c2 + 1]
            - prefix[r2 + 1][c1] + prefix[r1][c1])

class TrieNode:
    __slots__ = ("children", "is_end", "count")
    def __init__(self):
        self.children = {}
        self.is_end = False      # 是否是某个单词的结尾
        self.count = 0           # 经过该节点的单词数（用于前缀统计）

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
            node.count += 1
        node.is_end = True

    def search(self, word: str) -> bool:
        node = self._walk(word)
        return node is not None and node.is_end

    def starts_with(self, prefix: str) -> bool:
        return self._walk(prefix) is not None

    def count_prefix(self, prefix: str) -> int:
        node = self._walk(prefix)
        return node.count if node else 0

    def _walk(self, text: str):
        node = self.root
        for ch in text:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

from collections import deque

def next_greater(nums):
    """下一个更大元素的下标；不存在记 -1。"""
    result = [-1] * len(nums)
    stack = []                       # 存下标，对应值单调递减
    for i, value in enumerate(nums):
        while stack and nums[stack[-1]] < value:
            result[stack.pop()] = i
        stack.append(i)
    return result

def largest_rectangle(heights):
    """柱状图中最大矩形：单调递增栈，两端补 0 作哨兵。"""
    stack, best = [], 0
    for i, h in enumerate(list(heights) + [0]):
        while stack and heights[stack[-1]] > h:
            height = heights[stack.pop()]
            width = i if not stack else i - stack[-1] - 1
            best = max(best, height * width)
        stack.append(i)
    return best

def sliding_window_max(nums, k):
    """滑动窗口最大值：单调递减队列，队首即最大值。"""
    queue = deque()                  # 存下标
    result = []
    for i, value in enumerate(nums):
        while queue and nums[queue[-1]] <= value:
            queue.pop()              # 比新元素小的都不可能是最大值
        queue.append(i)
        if queue[0] <= i - k:        # 队首已滑出窗口
            queue.popleft()
        if i >= k - 1:
            result.append(nums[queue[0]])
    return result

def binary_answer(low, high, feasible):
    """求满足 feasible(x) 的最小 x（feasible 随 x 单调递增为真）"""
    while low < high:
        mid = (low + high) // 2
        if feasible(mid):
            high = mid          # mid 可行，尝试更小
        else:
            low = mid + 1       # mid 不可行，必须更大
    return low

class AVLNode:
    __slots__ = ("key", "left", "right", "height")

    def __init__(self, key):
        self.key, self.left, self.right, self.height = key, None, None, 1

def height(node) -> int:
    return node.height if node else 0

def update(node) -> None:
    node.height = 1 + max(height(node.left), height(node.right))

def rotate_right(y):
    x = y.left
    y.left = x.right
    x.right = y
    update(y)
    update(x)
    return x

def rotate_left(x):
    y = x.right
    x.right = y.left
    y.left = x
    update(x)
    update(y)
    return y

def rebalance(node):
    update(node)
    balance = height(node.left) - height(node.right)
    if balance > 1:
        if height(node.left.left) < height(node.left.right):
            node.left = rotate_left(node.left)     # LR
        return rotate_right(node)
    if balance < -1:
        if height(node.right.right) < height(node.right.left):
            node.right = rotate_right(node.right)  # RL
        return rotate_left(node)
    return node

from collections import OrderedDict

class LRUCache:
    """哈希表 + 双向链表：查询与更新都是 O(1)。"""

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("容量必须为正")
        self.capacity = capacity
        self.data = OrderedDict()
        self.hits = self.misses = 0

    def get(self, key):
        if key not in self.data:
            self.misses += 1
            return None
        self.data.move_to_end(key)          # 标记为最近使用
        self.hits += 1
        return self.data[key]

    def put(self, key, value) -> None:
        if key in self.data:
            self.data.move_to_end(key)
        self.data[key] = value
        if len(self.data) > self.capacity:
            self.data.popitem(last=False)   # 淘汰最久未使用

    def hit_rate(self) -> float:
        total = self.hits + self.misses
        return 0.0 if total == 0 else self.hits / total

