class Saga:
    def run(self, ctx):
        for name, action, compensate in self.actions:
            try:
                action(ctx)
                self.executed.append((name, compensate))
            except Exception:
                self.rollback(ctx)
                raise

    def rollback(self, ctx):
        for name, compensate in reversed(self.executed):   # 逆序补偿
            compensate(ctx)

